async function capabilities(c){const s={group_id:c.group,company_id:c.input.company_id,person_id:c.self?c.op.person_id:null},out={};for(const[k,res,action]of[['can_configure','learning_config','write'],['can_manage','learning_manage','write'],['can_grade','learning_grade','write'],['can_review','learning_grade','approve'],['can_publish','learning_publish','publish'],['can_apply','learning_apply','write'],['can_self','learning_self','read'],['can_import','learning_manage','import'],['can_export','learning_manage','export']])out[k]=await can(c,res,action,s);return out;}
async function options(c){const out=[];if(c.input.option_type==='operators'){await access(c,'learning_manage','write',{group_id:c.group,company_id:c.input.company_id},['task_reference']);for(const x of await q(c.t,`SELECT a.id,a.display_name,b.group_id,b.company_id,b.person_id FROM sys_account a JOIN ty_operator_binding b ON b.account_id=a.id WHERE a.status='active'AND b.status='active'AND b.group_id=$1 ORDER BY a.id`,[c.group])){if(!await wanted(c,x))continue;const v=await project(c,'learning_manage',{...x,full_name:x.display_name});if(v){delete v.display_name;out.push(v);}}}else{for(const e of await q(c.t,"SELECT e.*,e.id employment_id,p.full_name,p.person_number,c.name company_name FROM ty_employment e JOIN ty_person p ON p.id=e.person_id JOIN ty_company c ON c.id=e.company_id WHERE e.group_id=$1 AND e.status<>'cancelled'ORDER BY e.id",[c.group])){if(!await wanted(c,e))continue;const v=await project(c,c.self?'learning_self':'learning_manage',{...scope(e),id:e.id,employment_id:e.id,full_name:e.full_name,person_number:e.person_number,company_name:e.company_name,hire_date:e.hire_date,leave_date:e.leave_date});if(v)out.push(v);}}return out;}
