export async function personHistory(t,args){const c=await ctx(t,args);if(!c.input.person_id&&!c.self)bad('请明确永久人员编号');const sections={};for(const view of['enrollments','attendance','practicals','discipline','grades','recognitions','applications']){try{const result=await queryWorkspace(t,{...args,input:{...args.input,view}});sections[view]=result;}catch(e){if(!String(e.message).includes('E_TY_FORBIDDEN'))throw e;sections[view]={unavailable:true,reason:'当前无完整授权'};}}return{person_id:c.self?c.op.person_id:c.input.person_id,sections};}
