async function importRow(c,kind,input){if(kind==='questions')return configuration(c,'question');if(kind==='attendance')return evidence(c,'attendance');const e=await employment(c,input.employment_id);await access(c,'learning_manage','import',e,['scores','sources']);const req=await requirement(c,e,input.requirement_key,input.max_attempts??1),prev=await one(c.t,"SELECT * FROM ty_lr_grade WHERE requirement_id=$1 AND source_kind='historical'AND source_ref=$2 ORDER BY version DESC LIMIT 1",[req.id,input.source_ref]);if(prev)return{kind:'grade',id:prev.id};const score=scalar(input.score),max=scalar(input.maximum_score,'满分','0.000001'),threshold=scalar(input.pass_percentage??'60'),calculated=await one(c.t,'SELECT round($1::numeric*100/$2::numeric,6)::text percentage,round($1::numeric*100/$2::numeric,6)>=$3::numeric passed',[score,max,threshold]);if(await one(c.t,"SELECT 1 FROM ty_lr_attempt WHERE requirement_id=$1 AND status='in_progress'",[req.id]))bad('此要求仍在考试，历史导入须先核对未结答卷');await c.t.query('UPDATE ty_lr_requirement SET historical_quota_pending=true WHERE id=$1',[req.id]);const r=await ins(c,'grade',{...scope(e),employment_id:e.id,requirement_id:req.id,attempt_id:null,version:Number((await one(c.t,"SELECT coalesce(max(version),0)+1 n FROM ty_lr_grade WHERE requirement_id=$1 AND source_kind='historical'",[req.id])).n),marks:{},score,maximum_score:max,percentage:calculated.percentage,pass_percentage:threshold,passed:calculated.passed,source_hash:hash({employment_id:e.id,source_ref:input.source_ref,score,maximum_score:max,percentage:calculated.percentage}),source_kind:'historical',occurred_on:date(input.occurred_on),source_ref:text(input.source_ref,'历史原始来源',4),created_by:c.userId,reason:'历史成绩导入待核，未伪造答卷或签署记录'});return changed(c,'grade',r,'history.draft');}
async function importPreview(c){const i=c.input;await access(c,'learning_manage','import',{group_id:c.group,company_id:i.company_id},['sources','scores']);const kind=choice(i.kind,['questions','historical_grades','attendance']),raw=Buffer.from(text(i.content_base64,'文件内容',20,4500000),'base64');if(raw.length>3*1024*1024)bad('导入文件不得超过3MB');const book=readNamedWorkbook(raw);if(book.errors.length||book.formula_count||book.external_formula_count||book.external_relationship_count)bad('导入须使用无公式无外链的已核值XLSX');const s=book.sheets.find(x=>!x.hidden);if(!s||s.max_row<2||s.max_row>1001)bad('导入须1至1000条');const letters=n=>{let o='';for(;n;n=Math.floor((n-1)/26))o=String.fromCharCode(65+(n-1)%26)+o;return o;},headers=Array.from({length:s.max_column},(_,n)=>String(s.cells.get(letters(n+1)+'1')?.value??'').trim()),allowed=kind==='questions'?['code','kind','category','difficulty','prompt','options_json','answer_json','points','rubric']:kind==='attendance'?['assignment_id','session_id','check_in','check_out','credited_minutes','attendance_state','source_ref']:['employment_id','requirement_key','score','maximum_score','pass_percentage','occurred_on','source_ref'];if(new Set(headers).size!==headers.length||headers.some(h=>!allowed.includes(h)))bad('字段须使用本模块模板且不可重复');const parsed=[],issues=[];for(let n=2;n<=s.max_row;n++){const input={};for(let k=0;k<headers.length;k++){const cell=s.cells.get(letters(k+1)+n);if(cell?.value!==undefined&&cell.value!==null&&cell.value!=='')input[headers[k]]=cell.cell_type==='n'?cell.raw_value_text:String(cell.value);}if(!Object.keys(input).length)continue;try{if(kind==='questions'){input.options=JSON.parse(input.options_json??'[]');input.answer=JSON.parse(input.answer_json??'null');}await c.t.query('SAVEPOINT learning_import_row');try{await importRow({...c,input},kind,input);await c.t.query('ROLLBACK TO SAVEPOINT learning_import_row');await c.t.query('RELEASE SAVEPOINT learning_import_row');}catch(e){await c.t.query('ROLLBACK TO SAVEPOINT learning_import_row');await c.t.query('RELEASE SAVEPOINT learning_import_row');throw e;}parsed.push({row_number:n,input});}catch(e){issues.push({row:n,code:e.code??'E_TY_ARGUMENT',message:String(e.message).slice(0,400)});}}const namespace=text(i.namespace,'导入来源空间',4,100),digest=hash({kind,company_id:i.company_id??null,bytes:raw.toString('base64')}),old=await one(c.t,'SELECT id FROM ty_lr_import WHERE group_id=$1 AND namespace=$2 AND source_hash=$3',[c.group,namespace,digest]);if(old)return{kind:'import',id:old.id};const r=await ins(c,'import',{group_id:c.group,company_id:i.company_id?id(i.company_id):null,kind,namespace,filename:text(i.filename),source_hash:digest,parsed_rows:parsed,issues,status:issues.length?'invalid':'validated',created_by:c.userId});return changed(c,'import',r,'import.preview');}
async function importCommit(c){const b=await row(c,'import',c.input.id,true);await access(c,'learning_manage','import',b,['sources','scores']);revision(b,c.input.expected_revision);if(b.status!=='validated')conflict('仅预检通过且未采用的导入批次可提交');for(const r of b.parsed_rows)await importRow({...c,input:r.input},b.kind,r.input);const out=await one(c.t,"UPDATE ty_lr_import SET status='applied',revision=revision+1 WHERE id=$1 RETURNING *",[b.id]);return changed(c,'import',out,'import.commit');}
async function publishOperational(c,kind){const r=await row(c,kind,c.input.id,true);await access(c,'learning_manage','publish',r,[kind==='exam'?'exams':'tasks']);revision(r,c.input.expected_revision);await independent(c,r,r.created_by);if(r.status!=='draft')conflict('仅草稿可发布');if(kind==='exam'){const p=await row(c,'paper',r.paper_id);if(p.status!=='published'||!p.pool_snapshot.length)bad('试卷未完成审核');}const out=await one(c.t,`UPDATE ${TABLE[kind]} SET status='published',published_by=$2,revision=revision+1 WHERE id=$1 RETURNING *`,[r.id,c.userId]);return changed(c,kind,out,kind+'.publish');}
export const operations=Object.freeze(['course.save','course.publish','plan.save','plan.publish','enrollment.request','enrollment.decide','enrollment.cancel','assignment.create','progress.save','progress.complete','session.save','attendance.submit','attendance.verify','practical.submit','practical.verify','discipline.record','discipline.verify','question.save','question.publish','paper.save','paper.publish','exam.save','exam.publish','exam.assign','attempt.start','attempt.answer','attempt.submit','attempt.seal','attempt.extend','attempt.void','grade.propose','grade.approve','grade.publish','grade.acknowledge','appeal.submit','appeal.decide','certificate.save','certificate.publish','recognition.propose','recognition.approve','recognition.revoke','rule.save','rule.publish','application.preview','application.approve','application.execute','application.cancel','notice.read','import.preview','import.commit'].map(x=>'learning.'+x));
async function preflight(c,op){const[k,action]=op.split('.'),i=c.input;if(['course','question','paper','certificate','rule'].includes(k)){const r=action==='save'?{group_id:c.group,company_id:i.company_id}:await row(c,k,i.id);await access(c,'learning_config',action==='publish'?'publish':'write',r,['settings']);return;}if(k==='notice'){if(!await authorisedNotice(c,await row(c,'notice',i.id)))deny('提醒所关联业务当前不可读');return;}if(k==='progress'){const a=await row(c,'assignment',i.assignment_id);await own(c,a);return;}if(k==='attempt'){if(action==='start')await own(c,await row(c,'requirement',i.requirement_id));else await attemptAccess(c,i.id,{self:['answer','submit'].includes(action),grade:false,action:['extend','void'].includes(action)?'approve':'write'});return;}if(k==='grade'){if(action==='propose')await attemptAccess(c,i.attempt_id,{self:false,grade:true,action:'write'});else if(action==='acknowledge'){const p=await row(c,'publication',i.publication_id);await own(c,await row(c,'grade',p.grade_id));}else{const r=await row(c,'grade',i.id);await access(c,action==='publish'?'learning_publish':'learning_grade',action==='publish'?'publish':'approve',r,['scores']);}return;}if(k==='enrollment'&&action==='request'){await own(c,await employment(c,i.employment_id));return;}const kind={enrollment:'assignment',assignment:'plan',session:'plan',attendance:action==='verify'?'attendance':'assignment',practical:action==='verify'?'practical':'assignment',discipline:action==='verify'?'discipline':'assignment',recognition:action==='propose'?'requirement':'recognition',application:action==='preview'?'requirement':'application',appeal:action==='submit'?'publication':'appeal',import:'import'}[k]??k;let key=i.id??i.assignment_id??i.requirement_id??i.plan_id??i.exam_id??i.publication_id;if(k==='assignment'){const e=await employment(c,i.employment_id);await access(c,'learning_manage','create',e,['tasks']);return;}if(k==='session')key=i.plan_id;if(k==='exam'&&action==='assign'){const r=await row(c,'requirement',i.requirement_id);await access(c,'learning_manage','write',r,['tasks','exams']);return;}if(k==='plan'&&action==='save'||k==='exam'&&action==='save'||k==='import'&&action==='preview'){await access(c,'learning_manage',k==='import'?'import':'create',{group_id:c.group,company_id:i.company_id},[k==='exam'?'exams':'tasks']);return;}const r=await row(c,kind,key);if(k==='appeal'&&action==='submit'){await own(c,await row(c,'grade',r.grade_id));return;}if(k==='enrollment'&&action==='cancel'||k==='attendance'&&action==='submit'&&c.op.person_id&&same(c.op.person_id,r.person_id)){await own(c,r);return;}await access(c,RES[k]??'learning_manage',['verify','decide','approve','revoke'].includes(action)?'approve':action==='publish'?'publish':action==='commit'?'import':action==='execute'?'execute':'write',r);}
async function receipt(c,r){if(r.kind==='exam_assignment')return{exam_assignment_id:r.id,requirement_id:r.requirement_id,replayed:!!r.replayed};if(r.kind==='notice')return{notice_id:r.id,read:true,replayed:!!r.replayed};const value=await row(c,r.kind,r.id);if(r.kind==='attempt'){const {question_snapshot,...safe}=value;return{attempt:await project(c,c.op.person_id&&same(c.op.person_id,value.person_id)?'learning_self':'learning_manage',safe),replayed:!!r.replayed};}if(r.kind==='progress'){const a=await row(c,'assignment',value.assignment_id);await own(c,a);return{progress:{id:value.id,chapter_key:value.chapter_key,segments:value.segments,acknowledged:value.acknowledged,revision:value.revision},replayed:!!r.replayed};}if(r.kind==='import'){const safe={...value};delete safe.parsed_rows;return{import:await project(c,'learning_manage',safe),replayed:!!r.replayed};}const safe=await withPerson(c,value);if(r.kind==='question')delete safe.answer;const receiptContext=(['assignment','appeal'].includes(r.kind)||r.kind==='grade'&&c.operation==='grade.acknowledge')&&c.op.person_id&&same(c.op.person_id,value.person_id)?{...c,self:true}:c;const projectedValue=await projected(receiptContext,r.kind,safe);if(!projectedValue)deny('当前无完整权限读取办理回执');return{[r.kind]:projectedValue,replayed:!!r.replayed};}
export async function dispatchCommand(t,{userId,input,operation,operationId}){if(!operations.includes(operation))bad('未知培训考试命令');const c=await ctx(t,{userId,input});const op=operation.slice(9);c.operation=op;await preflight(c,op);return command(t,{userId,groupId:c.group,operation,operationId,input,project:r=>receipt(c,r),execute:async()=>{const[k,action]=op.split('.');if(['course','question','paper','certificate','rule'].includes(k))return action==='save'?configuration(c,k):publishConfig(c,k);if(k==='plan')return action==='save'?savePlan(c):publishOperational(c,k);if(k==='assignment')return assign(c);if(k==='enrollment')return action==='request'?assign(c,true):decideEnrollment(c,action==='cancel');if(k==='progress')return progress(c,action==='complete');if(k==='session')return saveSession(c);if(['attendance','practical','discipline'].includes(k))return evidence(c,k,action==='verify');if(k==='exam')return action==='save'?examSave(c):action==='assign'?examAssign(c):publishOperational(c,k);if(k==='attempt')return action==='start'?start(c):action==='answer'?answer(c):action==='submit'?seal(c):action==='seal'?seal(c,true):attemptException(c,action==='void');if(k==='grade'){if(action==='propose')return proposeGrade(c);if(action==='approve')return gradeApprove(c);if(action==='publish')return publishGrade(c);const p=await row(c,'publication',input.publication_id),g=await row(c,'grade',p.grade_id);await own(c,g);await t.query('UPDATE ty_lr_publication SET acknowledged_at=coalesce(acknowledged_at,now()),acknowledged_by=$2 WHERE id=$1',[p.id,userId]);return{kind:'grade',id:g.id};}if(k==='appeal')return appeal(c,action==='decide');if(k==='recognition')return recognition(c,action);if(k==='application')return application(c,action);if(k==='import')return action==='preview'?importPreview(c):importCommit(c);if(k==='notice'){await t.query('UPDATE ty_lr_notice SET read_at=coalesce(read_at,now())WHERE id=$1 AND recipient_id=$2',[id(input.id),userId]);return{kind:'notice',id:input.id};}bad('命令尚未开放');}});}
export async function workflowSource(t,{userId,id:key,kind='grade',forSubmission=true}){const r=await one(t,`SELECT * FROM ${kind==='grade'?'ty_lr_grade':'ty_lr_application'} WHERE id=$1`,[id(key)]);if(!r)missing();const c=await ctx(t,{userId,input:{group_id:r.group_id}});await access(c,kind==='grade'?'learning_grade':'learning_apply',forSubmission?'submit':'read',r,['sources',...(kind==='grade'?['scores']:['amount'])]);if(forSubmission&&(r.status!=='proposed'||!same(r.created_by,userId)))deny('只能提交本人创建且尚未办理的业务意图');const snapshot={id:r.id,kind,requirement_id:r.requirement_id,source_hash:r.source_hash,revision:r.revision,score:r.score??null,target_assignment_id:r.target_assignment_id??null};return{id:r.id,group_id:r.group_id,company_id:r.company_id,person_id:r.person_id,original_requester_id:r.created_by,hash:hash(snapshot),safe_title:kind==='grade'?'考试成绩复核':'培训结果采用核准',safe_values:{subject_id:r.id,group_id:r.group_id,company_id:r.company_id},snapshot};}
export async function assertWorkflowApproval(t,{userId,id:key,kind='grade'}){const r=await one(t,`SELECT * FROM ${kind==='grade'?'ty_lr_grade':'ty_lr_application'} WHERE id=$1`,[id(key)]);if(!r)missing();const c=await ctx(t,{userId,input:{group_id:r.group_id}});await access(c,kind==='grade'?'learning_grade':'learning_apply','approve',r,kind==='grade'?['scores','answers']:['sources','amount']);await independent(c,r,r.created_by);if(!['proposed','approved'].includes(r.status))conflict('该意图已撤回或处理');if(kind==='grade'&&r.attempt_id){const a=await row(c,'attempt',r.attempt_id),e=await row(c,'exam',a.exam_id);if(!same(e.reviewer_id,userId))deny('不是本考试指定成绩复核人');}return{r,c};}
export async function executeWorkflow(t,{userId,instance,kind='grade'}){const source=await workflowSource(t,{userId,id:instance.subject_id,kind,forSubmission:false}),flow=await import('./platform-workflow.mjs'),proof=await flow.verifyApprovalReceipt(t,{userId,instanceId:instance.id,subjectType:kind==='grade'?'learning_result':'learning_application',subjectId:String(source.id),sourceHash:source.hash});await assertWorkflowApproval(t,{userId:proof.approved_by,id:source.id,kind});const c=await ctx(t,{userId,input:{group_id:source.group_id,id:source.id,reason:'统一审批流实际核准:'+proof.instance_id}});await access(c,kind==='grade'?'learning_grade':'learning_apply','execute',source,['sources']);return command(t,{userId,groupId:source.group_id,operation:'learning.workflow.execute',operationId:'LR-WORKFLOW:'+proof.instance_id,input:{instance_id:proof.instance_id,source_hash:source.hash,kind},execute:async()=>{await t.query('SAVEPOINT learning_workflow_apply');try{const r=await row(c,kind==='grade'?'grade':'application',source.id,true);if(kind==='grade'){await one(t,"UPDATE ty_lr_grade SET status='approved',approved_by=$2,approval_instance_id=$3,reason=$4,revision=revision+1 WHERE id=$1 AND status='proposed'RETURNING id",[r.id,proof.approved_by,instance.id,c.input.reason]);}else{const current=await applicationSource(c,r,await row(c,'rule',r.rule_id));if((await one(t,'SELECT fn_ty_lr_hash($1::jsonb)h',[JSON.stringify(current.snapshot)])).h!==r.source_hash)conflict('来源已变');const approved=await one(t,"UPDATE ty_lr_application SET status='approved',approved_by=$2,approval_instance_id=$3,revision=revision+1 WHERE id=$1 AND status='proposed'RETURNING *",[r.id,proof.approved_by,instance.id]);if(!approved)conflict('培训应用提案已处理');await application({...c,input:{...c.input,id:approved.id,expected_revision:approved.revision}},'execute');}await t.query("UPDATE ty_workflow_instance SET business_state='applied',revision=revision+1 WHERE id=$1",[instance.id]);await t.query('RELEASE SAVEPOINT learning_workflow_apply');return{domain_applied:true,kind,subject_id:r.id,approved_by:proof.approved_by,execution_actor:userId};}catch(e){await t.query('ROLLBACK TO SAVEPOINT learning_workflow_apply');await t.query('RELEASE SAVEPOINT learning_workflow_apply');if(!['23514','40001','E_TY_CONFLICT','E_TY_ARGUMENT','E_TY_FORBIDDEN'].includes(e.code)&&!/^E_TY_(CONFLICT|ARGUMENT|FORBIDDEN):/.test(String(e.message)))throw e;await t.query("UPDATE ty_workflow_instance SET business_state='blocked',revision=revision+1 WHERE id=$1",[instance.id]);await emit(t,source.group_id,'learning:workflow:'+instance.id+':blocked','LearningExecutionNeedsReview',{instance_id:instance.id,subject_id:source.id,kind,domain_applied:false});return{blocked:true,source_changed:true,domain_applied:false};}}});}
export async function closeWorkflow(t,{userId,instance,kind='grade',cancel=false}){const source=await workflowSource(t,{userId,id:instance.subject_id,kind,forSubmission:false}),actual=await one(t,'SELECT * FROM ty_workflow_instance WHERE id=$1 FOR UPDATE',[instance.id]);if(!actual||actual.source_hash!==source.hash||!same(actual.applicant_id,source.original_requester_id))deny('不是原业务意图的真实流程回执');if(cancel){if(!same(userId,source.original_requester_id)||!['running','blocked','cancelled'].includes(actual.status))deny('不能撤回非本人或已办意图');}else{if(actual.status!=='rejected'||!same(actual.last_approver_id,userId)||!await one(t,"SELECT 1 FROM ty_workflow_task WHERE instance_id=$1 AND approver_id=$2 AND status='rejected'",[actual.id,userId]))deny('没有当前实际拒绝回执');await assertWorkflowApproval(t,{userId,id:source.id,kind});}const table=kind==='grade'?'ty_lr_grade':'ty_lr_application',r=await one(t,`UPDATE ${table} SET status=$2,reason=$3,revision=revision+1 WHERE id=$1 AND status='proposed'RETURNING id`,[source.id,kind==='grade'?'rejected':cancel?'cancelled':'rejected',cancel?'原申请人撤回审批意图':'真实独立拒绝回执']);if(!r)conflict('业务意图已处理');return{domain_cancelled:cancel,domain_rejected:!cancel,subject_id:r.id};}
export async function sealDueAttempts(t,{userId,input}){const c=await ctx(t,{userId,input}),out=[];for(const a of await q(t,"SELECT * FROM ty_lr_attempt WHERE group_id=$1 AND status='in_progress'AND deadline_at<=clock_timestamp()ORDER BY id LIMIT 100",[c.group])){if(!await can(c,'learning_manage','execute',a,['exams']))continue;const r=await seal({...c,input:{id:a.id,deadline_revision:a.deadline_revision}},true);out.push(r.id);}return{sealed_ids:out};}
async function catalog(c){if(!c.op.person_id)return[];const out=[],employments=await q(c.t,"SELECT * FROM ty_employment WHERE group_id=$1 AND person_id=$2 AND status<>'cancelled'AND hire_date<=app_today()AND(leave_date IS NULL OR leave_date>=app_today())ORDER BY company_id,id",[c.group,c.op.person_id]);for(const p of await q(c.t,"SELECT * FROM ty_lr_plan WHERE group_id=$1 AND status='published'AND ends_on>app_today()ORDER BY id DESC",[c.group])){for(const e of employments){if(p.company_id&&!(await companyDescendants(c.t,p.company_id)).includes(String(e.company_id))||!await wanted(c,e)||!await can(c,'learning_self','read',e,['tasks']))continue;const old=await one(c.t,"SELECT 1 FROM ty_lr_assignment WHERE plan_id=$1 AND employment_id=$2 AND state NOT IN('cancelled','rejected')",[p.id,e.id]);if(old)continue;const v=await project(c,'learning_self',{id:p.id,name:p.name,code:p.code,...scope(e),employment_id:e.id,starts_on:p.starts_on,ends_on:p.ends_on,status:'published',required_minutes:p.required_minutes,capacity:p.capacity});if(v)out.push(v);break;}}return out;}
const IMPORT_COLUMNS={questions:['code','kind','category','difficulty','prompt','options_json','answer_json','points','rubric'],historical_grades:['employment_id','requirement_key','score','maximum_score','pass_percentage','occurred_on','source_ref'],attendance:['assignment_id','session_id','check_in','check_out','credited_minutes','attendance_state','source_ref']};
export async function importTemplate(t,args){const c=await ctx(t,args),kind=choice(c.input.kind,Object.keys(IMPORT_COLUMNS));await access(c,'learning_manage','import',{group_id:c.group,company_id:c.input.company_id},['sources','scores']);return{filename:'ty-hr-learning-'+kind+'-template.xlsx',mime:XLSX_CONTENT_TYPE,content_base64:writeXlsx({sheetName:'导入模板',columns:IMPORT_COLUMNS[kind].map(key=>({key,label:key})),rows:[]}).toString('base64'),fields:IMPORT_COLUMNS[kind],instructions:'引用现有永久人和实际关系，不按姓名合并；历史成绩须填发生日和原始来源；预检仅待核草稿。'};}
export async function learningFileContext(t,{userId,ownerKind,ownerId,action='read'}){let r,res;if(ownerKind==='learning_attempt'){const a=await one(t,'SELECT * FROM ty_lr_attempt WHERE id=$1',[id(ownerId)]);if(!a)missing();const c=await ctx(t,{userId,input:{group_id:a.group_id}});if(c.op.person_id&&same(c.op.person_id,a.person_id)){await own(c,a);res='learning_self';}else{await attemptAccess(c,a.id,{self:false,grade:true,action});res='learning_grade';}await access(c,res,action,a,['answers','attachments']);r=a;}else if(ownerKind==='learning_practical'){r=await one(t,'SELECT * FROM ty_lr_practical WHERE id=$1',[id(ownerId)]);if(!r)missing();const c=await ctx(t,{userId,input:{group_id:r.group_id}});res='learning_manage';await access(c,res,action,r,['evidence','attachments']);}else if(ownerKind==='learning_course'){const course=await one(t,'SELECT * FROM ty_lr_course WHERE id=$1',[id(ownerId)]);if(!course)missing();const c=await ctx(t,{userId,input:{group_id:course.group_id}});if(await can(c,'learning_config',action,course,['content','attachments'])){r=course;res='learning_config';}else{if(action!=='read')deny();const a=await one(t,"SELECT a.* FROM ty_lr_assignment a JOIN ty_lr_plan p ON p.id=a.plan_id WHERE p.course_id=$1 AND a.person_id=$2 AND a.state IN('assigned','completed')ORDER BY a.id LIMIT 1",[course.id,c.op.person_id]);if(!a)deny();await own(c,a);await access(c,'learning_self','read',a,['content','attachments']);r={...course,...scope(a)};res='learning_self';}}else bad('未知学习附件归属');return{row:r,resource:res,fields:ownerKind==='learning_course'?['content','attachments']:['answers','attachments']};}

async function monthAllows(c,kind,r){if(!c.input.period)return true;const period=String(c.input.period).slice(0,7);if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period))bad('月份须YYYY-MM');const from=period+'-01',to=new Date(Date.UTC(Number(period.slice(0,4)),Number(period.slice(5,7)),1)).toISOString().slice(0,10),overlap=(start,end)=>date(start)<to&&(!end||date(end)>from);if(r.occurred_on)return date(r.occurred_on).slice(0,7)===period;if(kind==='assignment'){const p=await row(c,'plan',r.plan_id);return overlap(p.starts_on,p.ends_on);}if(kind==='plan')return overlap(r.starts_on,r.ends_on);if(kind==='attendance'||kind==='session'){const s=kind==='attendance'?await row(c,'session',r.session_id):r;const day=(await one(c.t,"SELECT ($1::timestamptz AT TIME ZONE 'Asia/Shanghai')::date AS business_day",[s.starts_at])).business_day;return date(day).slice(0,7)===period;}if(kind==='attempt'){const day=(await one(c.t,"SELECT ($1::timestamptz AT TIME ZONE 'Asia/Shanghai')::date AS business_day",[r.started_at])).business_day;return date(day).slice(0,7)===period;}if(kind==='recognition')return overlap(r.valid_from,r.valid_to);if(kind==='application'){const rule=await row(c,'rule',r.rule_id);if(rule.target==='payroll')return rule.config.mode==='once'?rule.config.payout_period===period:overlap(rule.config.valid_from,rule.config.valid_to);}return true;}
